"""Build a self-contained public-SAMPLE-only analysis/golfer/PDF preview.

No uploads, remote LLM calls, private conversations or original videos are embedded.
"""
from pathlib import Path
import argparse,json,base64,html
ROOT=Path(__file__).resolve().parents[1]
def build(sample,course,pdf,out):
    data=json.loads(Path(sample).read_text())
    # Export only analysis facts and body coordinates. Never a coaching transcript/profile.
    doc={k:data['doc'][k] for k in ('score','customer_report','positives')}
    customer=(ROOT/'web/customer-ui.js').read_text();customer=customer[customer.index('window.MotionCustomer='):]
    scripts='\n'.join((ROOT/'web'/p).read_text() for p in ('reference.js','pose-avatar.js','pose-project.js','video-evidence.js'))+'\n'+customer+'\n'+(ROOT/'web/motion-evidence.js').read_text()
    styles=(ROOT/'web/tokens.css').read_text()
    evidence=(ROOT/'web/style.css').read_text().split('/* Analysis first:')[1].split('*/',1)[1]
    pdfdata='data:application/pdf;base64,'+base64.b64encode(Path(pdf).read_bytes()).decode()
    course_html=html.escape(Path(course).read_text(),quote=True)
    text='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MotionGuard · 이미지 분석과 작은 골퍼</title><style>STYLES
*{box-sizing:border-box}body{margin:0;background:var(--paper-2);font:var(--t-body);color:var(--ink)}.preview{max-width:700px;background:var(--paper);margin:auto}.preview-head{padding:18px var(--gutter);border-bottom:1px solid var(--line)}.preview-head strong{font:var(--t-h2)}.preview-head p{font:var(--t-note);color:var(--ink-2)}nav{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}button,.download{font:var(--t-note);padding:10px;border:1px solid var(--line);border-radius:var(--r);min-height:var(--touch);background:var(--paper);color:var(--ink);cursor:pointer}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.pane{padding:var(--gutter)}h1{font:var(--t-h2)}.summary-note{font:var(--t-desc);color:var(--ink-2)}iframe{display:block;width:100%;height:2100px;border:0}.download{display:block;text-align:center;text-decoration:none;margin:16px 0}#detail-back{margin:12px 0}.evidence-card h3{margin-top:6px}.pdf-content{font:var(--t-desc);line-height:1.8}[hidden]{display:none!important}EVIDENCE</style><div class="preview"><header class="preview-head"><strong>MotionGuard</strong><p>실제 샘플 좌표의 분석 이미지 · 귀여운 골퍼 플레이</p><nav><button id="nav-analysis" aria-pressed="true">분석 결과</button><button id="nav-play" aria-pressed="false">작은 골퍼 플레이</button><button id="nav-pdf" aria-pressed="false">PDF 저장 결과</button></nav></header><section id="analysis" class="pane"><h1>내 스윙, 이미지로 확인해 보세요.</h1><p class="summary-note">잘한 점과 개선점을 선택하고, 해당 동작을 반복해서 볼 수 있어요.</p><button id="detail-back" hidden>← 전체 분석으로</button><div id="evidence"></div></section><section id="play" hidden><iframe id="play-frame" title="작은 골퍼가 스윙하고 공이 날아가는 가상 플레이" srcdoc="COURSE"></iframe></section><section id="pdf" class="pane" hidden><h1>분석 이미지 중심의 PDF</h1><p class="pdf-content">스윙 분석 요약<br>잘한 점·개선점의 현재/교정 가이드 이미지<br>관찰 내용과 연습 방법<br>측정 근거와 재지 못한 항목</p><p class="summary-note">기본 PDF는 5페이지이며 가상 타수는 내보내지 않아요. 앱에서 선택하면 코스 기록도 추가할 수 있어요.</p><a class="download" href="PDFDATA" download="motionguard-analysis-report.pdf">분석 이미지 PDF 열기·저장</a></section></div><script>SCRIPTS
const sample=SAMPLE;const root=document.getElementById('evidence');function render(){document.getElementById('detail-back').hidden=true;MotionEvidence.render(root,sample.doc,sample.track,detail);}function detail(id){MotionEvidence.stopAll();const positives=MotionEvidence.positives(sample.doc),improvements=MotionCustomer.improvements(sample.doc);const positive=positives.find(i=>i.id===id),item=improvements.find(i=>i.id===id);MotionEvidence.render(root,{...sample.doc,positives:positive?[positive]:[],customer_report:{...sample.doc.customer_report,improvements:item?[item]:[]}},sample.track,detail);document.getElementById('detail-back').hidden=false;window.scrollTo(0,0)}document.getElementById('detail-back').onclick=render;function show(name){MotionEvidence.stopAll();for(const id of ['analysis','play','pdf']){document.getElementById(id).hidden=id!==name;document.getElementById('nav-'+id).setAttribute('aria-pressed',id===name);}try{const doc=document.getElementById('play-frame').contentDocument;const b=doc?.getElementById('course-play');if(name!=='play'&&b?.textContent==='일시정지')b.click();}catch{}window.scrollTo(0,0)}for(const id of ['analysis','play','pdf'])document.getElementById('nav-'+id).onclick=()=>show(id);render();</script></html>'''
    text=text.replace('STYLES',styles).replace('EVIDENCE',evidence).replace('COURSE',course_html).replace('PDFDATA',pdfdata).replace('SCRIPTS',scripts).replace('SAMPLE',json.dumps({'doc':doc,'track':data['track']},ensure_ascii=False,allow_nan=False))
    Path(out).write_text(text);print(out)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--sample',required=True);p.add_argument('--course',required=True);p.add_argument('--pdf',required=True);p.add_argument('--out',required=True);a=p.parse_args();build(a.sample,a.course,a.pdf,a.out)
